    cards: [
      { front: "Адамзаттың даму жолы", back: "Епті адам (австралопитек): 1 млн 750 мың жыл бұрын, Олдувай шатқалы; епкейіп жүрген, қарапайым құралдар. Питекантроп: 1 млн жыл бұрын, 1891 ж. Ява аралы; тік жүрген, ми көлемі 950 см³. Синантроп: 500–200 мың жыл бұрын, 1927 ж. Қытай, Чжоу-коу-дянь үңгірі; отты пайдаланған, ми 1075 см³. Неандерталь: 100–35 мың жыл бұрын, 1856 ж. Германия; от жағуды үйренген. Саналы адам: 40–12 мың жыл бұрын, 1868 ж. Франция, Кро-Маньон; қазіргі адамға ұқсас, анық сөйлеген." },
      { front: "Табиғатпен күрес және тобыр", back: "Қиындықтар: қатал табиғат жағдайы; жыртқыш аңдардың шабуылы (үңгір аюлары, арыстандар); жеке жүріп азық табудың қиындығы. Шешім: тобыр — адамдар қорғану және бірлесіп аң аулау үшін алғашқы ұжым құрды. Үңгір — ең алғашқы табиғи баспана. Рулық қауым: кейінгі палеолитте тобыр бірте-бірте қандас туыстардың ұжымына — руға айналды." },
      { front: "Отты бағындыру — ең ұлы жеңіс", back: "Кездейсоқ от: найзағай түсіп жанған ағаштың отын алғашында өшірмей ұзақ сақтады. Отты өндіру: тастан шыққан ұшқынмен немесе ағашты бір-біріне үйкеп от жағуды үйренді. Пайдасы: жылыну (қатал суықтан қорғанды), қорғаныс (жыртқыш аңдарды үркітті), тамақ (ас пісіру мүмкіндігі туды, бұл мидың дамуына әсер етті)." },
      { front: "Терімшілік пен аңшылық", back: "Терімшілік: жеміс-жидектер, жеуге жарамды шөп тамырлары, құс жұмыртқалары. Тұрақты күнделікті азық көзі болды. Бастапқыда барлық жұмысты аналар атқарып, ұжымда аналар беделі артты. Аңшылық: мамонт, бизон, марал, жабайы жылқы, үңгір аюы. Тәсілдері: аңдарды толассыз қуалап болдыру; отпен үркітіп терең орға түсіру немесе биік құздан құлату." },
      { front: "Тас дәуірінің кезеңдері", back: "Палеолит (ежелгі тас ғасыры): б.з.б. 2,6 млн – 12 мың жыл; адамзат тарихының басталуы, алғашқы қарапайым тас құралдар, Олдувай және Ашель мәдениеттері. Мезолит (орта тас ғасыры): б.з.б. 12–5 мың жыл; мұздықтың еруі, микролиттер мен садақтың пайда болуы. Неолит (жаңа тас ғасыры): б.з.б. 5–3 мың жыл; егіншілік пен мал шаруашылығының қалыптасуы, тасты тесу және жылтырата тегістеу." },
      { front: "Тас өңдеу технологиясының кемелденуі", back: "Адамның жануарлардан басты айырмашылығы — еңбек құралын жасай білуі. 1-қадам: жару әдісі — тасты шетінен бастап ортасына қарай жарып, үшкір жаңқалар алу. 2-қадам: ретушь әдісі — бір қабат өңделген тас құралдың жүзіне ұсақ кертік ойықтар жасау арқылы оны өте өткір ету (Мустье кезеңі). 3-қадам: мамандандырылған құралдар — қырғыш (аң терісін тазалауға) және сүйек ине мен біз (киім тігуге)." },
      { front: "Қазақстан жері — ежелгі адамдардың қутты қонысы", back: "1) Оңтүстік Қазақстан (Қаратау, Арыстанды): Бөріқазған мен Шабақты тұрақтарынан 5000-ға жуық тас құрал табылды. 2) Батыс Қазақстан: Шақпақата тұрағы, Маңғыстаудан 1 млн жыл бұрынғы тас құралдар. 3) Орталық Қазақстан: Батпақ және Семізбұғы тұрақтары, 300-ге таяу тас қырғыш. 4) Шығыс Қазақстан: Шульбинка тұрағы, кейінгі палеолитке жататын ескерткіштер." },
      { front: "Рухани өмір, өнер және Ботай", back: "Тотемизм — рудың түпкі ата-бабасы жануар немесе құс деп сену. Анимизм — табиғаттың, судың, ағаштың өз рухы бар деп сену; кейін Тәңірлік дінге ұласты. Жерлеу ғұрпы — о дүниедегі өмірге сену, қасына қару-жарағы мен әшекейлерін бірге көму. Өнер: пиктография (суретті хат; күмір мен қызыл охра), сүйек пен мүйізден жасалған мүсіндер, қыш ыдыстардағы өрнектер. Ботай (Солтүстік Қазақстан, Айыртау ауданы, энеолит): 15 гектар, 158 үй; В.Ф. Зайберт; жылқыны алғаш қолға үйрету орталығы." },
    ],
